#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <ctype.h>

/* Return 1 if the given year is a leap year in the Gregorian calendar. */
static int is_leap(int year)
{
    /* The original code does not impose any limits on the year,
       it only uses the usual Gregorian rules. */
    return (year % 4 == 0) && (year % 100 != 0 || year % 400 == 0);
}

/* Validate a date string of the form YYYY-MM-DD.
   Returns 1 for a valid date, 0 otherwise. */
static int validate_date(const char *s)
{
    int year, month, day;
    static const int mdays[12] = {
        31, 28, 31, 30, 31, 30,
        31, 31, 30, 31, 30, 31
    };

    /* Length must be exactly 10 characters. */
    if (strlen(s) != 10)
        return 0;

    /* Expected format: 4 digits, '-', 2 digits, '-', 2 digits */
    if (!isdigit((unsigned char)s[0]) || !isdigit((unsigned char)s[1]) ||
        !isdigit((unsigned char)s[2]) || !isdigit((unsigned char)s[3]) ||
        s[4] != '-' ||
        !isdigit((unsigned char)s[5]) || !isdigit((unsigned char)s[6]) ||
        s[7] != '-' ||
        !isdigit((unsigned char)s[8]) || !isdigit((unsigned char)s[9]))
        return 0;

    /* Convert the ASCII digits to integer values. */
    year  = (s[0] - '0') * 1000 + (s[1] - '0') * 100 +
            (s[2] - '0') * 10   + (s[3] - '0');

    month = (s[5] - '0') * 10 + (s[6] - '0');
    day   = (s[8] - '0') * 10 + (s[9] - '0');

    /* Basic range checks. */
    if (month < 1 || month > 12)
        return 0;
    if (day < 1)
        return 0;

    /* Determine the maximum day for the given month (leap-year aware). */
    int max_day = mdays[month - 1];
    if (month == 2 && is_leap(year))
        max_day = 29;

    if (day > max_day)
        return 0;

    return 1;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("INVALID");
        return 0;
    }

    if (validate_date(argv[1]))
        puts("VALID");
    else
        puts("INVALID");

    return 0;
}
